exercise.solution:
function mediaDosUltimos(valores, n) {
  const ultimos = valores.slice(-n)

  // Sem valor nenhum nao ha media: 0 em vez de 0/0, que daria NaN.
  // Este caso so aparece DEPOIS de corrigir o divisor — e e o passo 8.
  if (ultimos.length === 0) return 0

  let soma = 0
  for (const valor of ultimos) soma += valor

  // A causa: dividia pela janela pedida, nao pelos valores que existem.
  return soma / ultimos.length
}

