function calcular(tipo, valor) {
  if (tipo === 'a') return valor * 2
  else if (tipo === 'b') return valor + 10
  else if (tipo === 'c') return 0
  return null
}

// a tabela separa o que varia do que decide
const regras = {
  a: (valor) => valor * 2,
  b: (valor) => valor + 10,
  c: () => 0,
}

function calcular(tipo, valor) {
  const regra = regras[tipo]
  return regra ? regra(valor) : null
}

