exercise.solution:
const FRETES = {
  economico: (peso) => 10 + 2 * peso,
  expresso: (peso) => 20 + 4 * peso,
  retirada: () => 0,
}

function calcularFrete(tipo, peso) {
  const regra = FRETES[tipo]
  if (!regra) return null
  return regra(peso)
}

function tiposDisponiveis() {
  return Object.keys(FRETES).sort()
}

