// Faz tudo: conhece o formato do banco, decide a regra e formata a saída.
function resumoDoCarrinho(linhas, cupom) {
  let total = 0
  for (const linha of linhas) {
    total += linha.preco_unitario * linha.qtd
  }
  if (cupom === 'PRIMEIRA') total = total * 0.9
  return 'Total: R$ ' + total.toFixed(2)
}

questions.solution:
// A regra, testável sem passar pelo texto.
function calcularTotal(linhas, cupom) {
  const soma = linhas.reduce((total, linha) => total + linha.preco_unitario * linha.qtd, 0)
  return cupom === 'PRIMEIRA' ? soma * 0.9 : soma
}

// Só formata. O texto é o mesmo de antes, porque é contrato de tela.
function resumoDoCarrinho(linhas, cupom) {
  return 'Total: R$ ' + calcularTotal(linhas, cupom).toFixed(2)
}
